import{_ as l,W as t,s as o,u as r,I as s,ah as d,w as n,Z as p,A as i}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const f=JSON.parse('{"title":"如何在 RHEL 8 上安装 FreeIPA 客户端 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 8 上安装 FreeIPA 客户端 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 RHEL 8 上安装 FreeIPA 客户端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 8 上安装 FreeIPA 客户端 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230502.1 ⭐️ How to Install FreeIPA Client on RHEL  Rocky Linux  AlmaLinux","title":"如何在 RHEL 8 上安装 FreeIPA 客户端","tag":"202305"},"relativePath":"202305/20230502.1 ⭐️ How to Install FreeIPA Client on RHEL  Rocky Linux  AlmaLinux.md","filePath":"[post].md"}'),u={name:"202305/20230502.1 ⭐️ How to Install FreeIPA Client on RHEL  Rocky Linux  AlmaLinux.md"};function m(c,a,h,g,x,L){const e=t("Link");return r(),o("div",null,[a[18]||(a[18]=s("h1",{id:"如何在-rhel-8-上安装-freeipa-客户端",tabindex:"-1"},[n("如何在 RHEL 8 上安装 FreeIPA 客户端 "),s("a",{class:"header-anchor",href:"#如何在-rhel-8-上安装-freeipa-客户端","aria-label":"Permalink to 如何在 RHEL 8 上安装 FreeIPA 客户端"},"​")],-1)),a[19]||(a[19]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202305/12/182652jucsshn48zogzs1h.jpg",alt:""})],-1)),a[20]||(a[20]=s("blockquote",null,[s("p",null,"在本文中，我们将向你展示如何在 RHEL、Rocky Linux 或 AlmaLinux 上安装和配置 FreeIPA 客户端。")],-1)),s("p",null,[a[1]||(a[1]=n("为了演示，我们在 RHEL 系统上集成了 ")),p(e,{href:"https://linux.cn/article-15783-1.html"},{default:i(()=>a[0]||(a[0]=[n("FreeIPA 服务器")])),_:1}),a[2]||(a[2]=n("，使用 FreeIPA 进行集中认证。"))]),a[21]||(a[21]=d(`<p>FreeIPA 服务器是一个开源的身份管理解决方案，为 Linux 系统提供集中的身份验证、授权和帐户信息。</p><h3 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to 先决条件">​</a></h3><ul><li>已预装 RHEL 9/8 或 Rocky Linux 9/8 或 AlmaLinux 9/8</li><li>具有 sudo 权限的普通用户</li><li>RHEL 系统的有效订阅。</li><li>互联网连接</li></ul><p>事不宜迟，让我们深入了解 FreeIPA 客户端安装和配置步骤，</p><h3 id="_1、在-freeipa-服务器上创建一个用户" tabindex="-1">1、在 FreeIPA 服务器上创建一个用户 <a class="header-anchor" href="#_1、在-freeipa-服务器上创建一个用户" aria-label="Permalink to 1、在 FreeIPA 服务器上创建一个用户">​</a></h3><p>登录到 FreeIPA 服务器并创建一个用户以进行集中身份验证，这里我使用以下命令使用创建了一个用户 <code>opsadm</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo kinit admin</span></span>
<span class="line"><span>$ sudo ipa user-add opsadm --first=Ops --last=Admin --password</span></span>
<span class="line"><span>Password:</span></span>
<span class="line"><span>Enter Password again to verify:</span></span>
<span class="line"><span>-------------------</span></span>
<span class="line"><span>Added user &quot;opsadm&quot;</span></span>
<span class="line"><span>-------------------</span></span>
<span class="line"><span>  User login: opsadm</span></span>
<span class="line"><span>  First name: Ops</span></span>
<span class="line"><span>  Last name: Admin</span></span>
<span class="line"><span>  Full name: Ops Admin</span></span>
<span class="line"><span>  Display name: Ops Admin</span></span>
<span class="line"><span>  Initials: OA</span></span>
<span class="line"><span>  Home directory: /home/opsadm</span></span>
<span class="line"><span>  GECOS: Ops Admin</span></span>
<span class="line"><span>  Login shell: /bin/bash</span></span>
<span class="line"><span>  Principal name: opsadm@LINUXTECHI.LAN</span></span>
<span class="line"><span>  Principal alias: opsadm@LINUXTECHI.LAN</span></span>
<span class="line"><span>  User password expiration: 20230502010113Z</span></span>
<span class="line"><span>  Email address: opsadm@linuxtechi.lan</span></span>
<span class="line"><span>  UID: 464600004</span></span>
<span class="line"><span>  GID: 464600004</span></span>
<span class="line"><span>  Password: True</span></span>
<span class="line"><span>  Member of groups: ipausers</span></span>
<span class="line"><span>  Kerberos keys available: True</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="_2、为-rhel、rocky-linux-或-almalinux-添加-dns-记录" tabindex="-1">2、为 RHEL、Rocky Linux 或 AlmaLinux 添加 DNS 记录 <a class="header-anchor" href="#_2、为-rhel、rocky-linux-或-almalinux-添加-dns-记录" aria-label="Permalink to 2、为 RHEL、Rocky Linux 或 AlmaLinux 添加 DNS 记录">​</a></h3><p>下一步是为我们想要与 FreeIPA 服务器集成以集中身份验证的机器添加 DNS 记录。在 FreeIPA 服务器上，运行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo ipa dnsrecord-add linuxtechi.lan rhel.linuxtechi.lan --a-rec 192.168.1.2</span></span></code></pre></div><p>注意：在上述命令中<strong>替换</strong>为你自己的 IP 地址和主机名。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/Add-DNS-Record-RHEL-RockyLinux-AlmaLinux-1024x73.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>现在登录到 RHEL 客户端并在 <code>/etc/hosts</code> 文件中添加以下条目：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>192.168.1.102 ipa.linuxtechi.lan ipa</span></span>
<span class="line"><span>192.168.1.2   rhel.linuxtechi.lan rhel</span></span></code></pre></div><p>保存并退出文件。</p><h3 id="_3、在-rhel、rockylinux-和-almalinux-上安装和配置-freeipa-客户端" tabindex="-1">3、在 RHEL、RockyLinux 和 AlmaLinux 上安装和配置 FreeIPA 客户端 <a class="header-anchor" href="#_3、在-rhel、rockylinux-和-almalinux-上安装和配置-freeipa-客户端" aria-label="Permalink to 3、在 RHEL、RockyLinux 和 AlmaLinux 上安装和配置 FreeIPA 客户端">​</a></h3><p>FreeIPA 客户端及其依赖项在默认软件包仓库（AppStream 和 BaseOS）中可用，因此要安装 FreeIPA 客户端，请运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install freeipa-client -y</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/Install-FreeIPA-Client-DNF-Command-RHEL.png" alt=""></p><p>安装完成后，配置 FreeIPA 客户端，运行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo ipa-client-install --hostname=\`hostname -f\` --mkhomedir --server=ipa.linuxtechi.lan --domain linuxtechi.lan  --realm LINUXTECHI.LAN</span></span></code></pre></div><p>根据你的设置<strong>替换</strong> FreeIPA 服务器的主机名、域名和领域。</p><p>输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/Configure-freeipa-client-command-rhel-1024x618.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>完美，上面的输出确认 <code>freeipa-client</code> 命令已成功执行。要测试 FreeIPA 客户端集成，请从当前用户注销并尝试以我们在 IPA 服务器上创建的 <code>opsadm</code> 用户身份登录。</p><h3 id="_4、测试-freeipa-客户端" tabindex="-1">4、测试 FreeIPA 客户端 <a class="header-anchor" href="#_4、测试-freeipa-客户端" aria-label="Permalink to 4、测试 FreeIPA 客户端">​</a></h3><p>试着在你刚刚配置了 FreeIPA 客户端的 RHEL 系统上使用 <code>opsadm</code> 用户通过 SSH 登录。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ssh opsadm@&lt;IPAddress-RHEL&gt;</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/First-time-login-opsadm-freeipa-rhel.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>当我们第一次登录系统时，由于密码过期政策，它会提示你设置新密码。</p><p>修改密码后，再次尝试登录。这次你应该可以登录了。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/Login-RHEL-System-FreeIPA-Client-1024x198.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>很好，上面的输出确认我们可以使用 <code>opsadm</code> 用户登录。这确认 FreeIPA 客户端安装和配置成功。</p><p>以上就是这篇文章的全部内容，希望你发现它提供了丰富的信息，请在下面的评论部分中发表你的疑问和反馈。</p><p><em>（题图：MJ/583ee400-3bad-4036-a725-f9d2078d69ab）</em></p><hr>`,36)),s("p",null,[a[4]||(a[4]=n("via: ")),p(e,{href:"https://www.linuxtechi.com/install-freeipa-client-on-rhel-rockylinux-almalinux/"},{default:i(()=>a[3]||(a[3]=[n("https://www.linuxtechi.com/install-freeipa-client-on-rhel-rockylinux-almalinux/")])),_:1})]),s("p",null,[a[9]||(a[9]=n("作者：")),p(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:i(()=>a[5]||(a[5]=[n("Pradeep Kumar")])),_:1}),a[10]||(a[10]=n(" 选题：")),p(e,{href:"https://github.com/lkxed/"},{default:i(()=>a[6]||(a[6]=[n("lkxed")])),_:1}),a[11]||(a[11]=n(" 译者：")),p(e,{href:"https://github.com/geekpi"},{default:i(()=>a[7]||(a[7]=[n("geekpi")])),_:1}),a[12]||(a[12]=n(" 校对：")),p(e,{href:"https://github.com/wxy"},{default:i(()=>a[8]||(a[8]=[n("wxy")])),_:1})]),s("p",null,[a[15]||(a[15]=n("本文由 ")),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>a[13]||(a[13]=[n("LCTT")])),_:1}),a[16]||(a[16]=n(" 原创编译，")),p(e,{href:"https://linux.cn/"},{default:i(()=>a[14]||(a[14]=[n("Linux中国")])),_:1}),a[17]||(a[17]=n(" 荣誉推出"))])])}const I=l(u,[["render",m]]);export{f as __pageData,I as default};
